css:
@keyframes highlight-sweep {
  from {
    background-size: 0% 100%;
  }

  to {
    background-size: 100% 100%;
  }
}

@keyframes highlight-fade {
  from {
    opacity: 0;
  }
}

HZhkp90k.css:
transition:
  background 150ms var(--ease-out),
  box-shadow 150ms var(--ease-out);
cursor: pointer;

&:hover {
  box-shadow: 0 0 0 3px {color.accent-soft};
}

&:focus-visible {
  outline: 2px solid {color.accent};
  outline-offset: 2px;
}

K2A7iETC.css:
transition:
  opacity 400ms ease,
  translate 400ms ease;

@starting-style {
  opacity: 0;
  translate: 0 100%;
}

KLaQXYk7.css:
cursor: pointer;

& > * {
  transition: box-shadow {transition.duration-pop} {ease.out};
}

&:hover > * {
  box-shadow: 0 0 0 2px {color.surface-3}, 0 0 0 4px {color.ink-3};
}

&:focus-visible {
  outline: none;
}

&:focus-visible > * {
  box-shadow: 0 0 0 2px {color.surface-3}, 0 0 0 4px {color.accent};
}

RV1DOgzp.css:
transition:
  box-shadow {transition.duration-press} {ease.out},
  background-color {transition.duration-press} {ease.out},
  color {transition.duration-press} {ease.out},
  scale {transition.duration-press} {ease.out};

&:hover {
  box-shadow: inset 0 0 0 100px color-mix(in oklab, {color.ink} 6%, transparent);
  color: {color.ink};
}

&:active {
  box-shadow: inset 0 0 0 100px color-mix(in oklab, {color.ink} 12%, transparent);
  scale: 0.97;
}

&:hover > :last-child {
  opacity: 1;
  scale: 1;
}

&:focus-visible {
  outline: 2px solid {color.accent};
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  scale: none;
  translate: none;
}

rBDgEEOC.css:
transition:
  opacity {transition.duration-pop} {ease.out},
  scale {transition.duration-pop} {ease.out},
  translate {transition.duration-pop} {ease.out};
transform-origin: bottom center;

@starting-style {
  opacity: 0;
  scale: 0.95;
  translate: 0 8px;
}

&[data-state="closed"] {
  opacity: 0;
  scale: 0.95;
  translate: 0 8px;
  transition-duration: {transition.duration-pop-exit};
}

@media (prefers-reduced-motion: reduce) {
  transition-property: opacity;
}

